package pt.arquivo.utils;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

import javax.imageio.ImageIO;

/**
 * Helpers to check screenshots generated by the webapp.
 *
 * <p>
 * Rendered pixels vary with the renderer version, fonts and how broken images
 * are drawn, so tests check that a screenshot is a valid, non blank image
 * instead of comparing checksums.
 * </p>
 */
public class ImageUtils {

	/**
	 * Decode image bytes, failing if they aren't an image (e.g. an HTML error page).
	 */
	public static BufferedImage readImage(byte[] bytes) {
		BufferedImage image;
		try {
			image = ImageIO.read(new ByteArrayInputStream(bytes));
		} catch (IOException e) {
			throw new RuntimeException("Error decoding image", e);
		}
		if (image == null) {
			String start = new String(bytes, 0, Math.min(bytes.length, 100));
			throw new AssertionError("Response isn't an image, it starts with: " + start);
		}
		return image;
	}

	/**
	 * Percentage of pixels that aren't white, used to detect blank renders.
	 */
	public static double nonWhitePercentage(BufferedImage image) {
		long nonWhite = 0;
		for (int y = 0; y < image.getHeight(); y++) {
			for (int x = 0; x < image.getWidth(); x++) {
				if ((image.getRGB(x, y) & 0xFFFFFF) != 0xFFFFFF) {
					nonWhite++;
				}
			}
		}
		return 100.0 * nonWhite / ((long) image.getWidth() * image.getHeight());
	}
}
